const userId = String(from.id || '');
const rawText = message.text || callbackData || '';
const normalizedText = rawText.trim().toLowerCase().replace(/ё/g, 'е').replace(/[.!?,]+$/g, '');
const greetingText = 'Здравствуйте. Я HR/legal RAG-ассистент TestRag. Задайте вопрос по кадровым, юридическим или договорным документам — отвечу по базе знаний и покажу источники.\n\nКоманды: /help, /history, /docs, /clear.';
const helpText = '<b>Чем могу помочь:</b>\n• Отвечаю на вопросы по HR, кадровому делопроизводству, договорам, претензиям, авиагрузовой логистике (AWB/MAWB/HAWB, controlled zone, dangerous goods, GHA, ULD, cutoff).\n• Каждый ответ ссылается на конкретные документы из корпуса.\n• Кнопками 👍/👎 отметьте качество — это попадает в очередь ревью.\n\n<b>Примеры вопросов:</b>\n• Что такое controlled zone?\n• Какие документы нужны для отправки dangerous goods авиатранспортом?\n• Какие основания для досрочного расторжения трудового договора?\n\n<b>Команды:</b>\n/help — это сообщение\n/history — мои последние 5 запросов\n/docs — что есть в корпусе\n/clear — про сохранение состояния';
const clearText = 'Состояние не сохраняется между запросами — каждый ответ автономен и не зависит от предыдущих. Для обращения к старым ответам используйте /history.';
const REASON_KEYS = ['inaccurate', 'outdated', 'human'];
let eventType = isFeedback ? 'feedback' : 'question';
let text = rawText;
let rating = null;
let category = null;
let requestLogId = null;
if (isFeedback) {
  const verb = feedbackParts[1] || '';
  requestLogId = feedbackParts[2] || null;
  if (verb === 'good') {
    rating = 'good';
  } else if (verb === 'bad') {
    eventType = 'feedback_bad_clarify';
    rating = null;
  } else if (verb.startsWith('bad_')) {
    const reasonKey = verb.slice(4);
    if (REASON_KEYS.includes(reasonKey)) {
      rating = 'bad';
      category = reasonKey;
    } else {
      eventType = 'direct_reply';
      text = 'Неизвестная причина обратной связи.';
    }
  } else {
    eventType = 'direct_reply';
    text = 'Неизвестная команда обратной связи.';
  }
}
if (!isFeedback && !normalizedText) {
  eventType = 'direct_reply';
  text = 'Пока я понимаю только текстовые вопросы. Задайте вопрос по HR, юридическим или договорным документам одним сообщением.';
}
if (!isFeedback && ['привет', 'здравствуйте', 'добрый день', 'доброе утро', 'добрый вечер', 'hello', 'hi', '/start', 'start'].includes(normalizedText)) {
  eventType = 'direct_reply';
  text = greetingText;
}
if (!isFeedback && ['спасибо', 'благодарю'].includes(normalizedText)) {
  eventType = 'direct_reply';
  text = 'Пожалуйста. Если нужен разбор по HR/legal документам, задайте вопрос одним сообщением.';
}
if (!isFeedback && (normalizedText === '/help' || normalizedText === 'help')) {
  eventType = 'direct_reply';
  text = helpText;
}
if (!isFeedback && (normalizedText === '/clear' || normalizedText === 'clear')) {
  eventType = 'direct_reply';
  text = clearText;
}
if (!isFeedback && (normalizedText === '/history' || normalizedText === 'history')) {
  eventType = 'history_request';
  text = '/history';
}
if (!isFeedback && (normalizedText === '/docs' || normalizedText === 'docs')) {
  eventType = 'docs_request';
  text = '/docs';
}
if (!allowed.length) {
  return [{ json: { authorized: false, chat_id: message.chat?.id, user_id: userId, text: `Whitelist не настроен. Ваш Telegram ID: ${userId}. Добавьте его в ALLOWED_TELEGRAM_USER_IDS в локальном .env и перезапустите n8n.` } }];
}
if (!allowed.includes(userId)) {
  return [{ json: { authorized: false, chat_id: message.chat?.id, user_id: userId, text: `Доступ запрещен. Ваш Telegram ID: ${userId}.` } }];
}
return [{ json: { authorized: true, event_type: eventType, chat_id: message.chat?.id, message_id: messageId, user_id: userId, text, rating, category, request_log_id: requestLogId } }];

const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const pluralRu = (n) => {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return ['Последний', 'запрос'];
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return ['Последние', 'запроса'];
  return ['Последние', 'запросов'];
};
const items = ($json.items || []);
if (!items.length) {
  return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text: 'История запросов пуста. Задайте первый вопрос — он попадёт в /history.' } }];
}
const lines = items.map((it, i) => {
  const q = escapeHtml(it.question || '').slice(0, 120);
  const when = (it.created_at || '').slice(0, 16).replace('T', ' ');
  const tag = it.refused ? ' [отказ]' : '';
  return `${i + 1}. <b>${when}</b>${tag}\n   <code>${q}</code>`;
}).join('\n\n');
const [prefix, noun] = pluralRu(items.length);
const text = `<b>${prefix} ${items.length} ${noun}:</b>\n\n${lines}`;
return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text } }];

const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cats = ($json.categories || []);
const total = $json.total_docs || 0;
if (!cats.length) {
  return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text: 'Корпус пуст или не загружен.' } }];
}
const lines = cats.map(c => `• ${escapeHtml(c.label)} — ${c.doc_count}`).join('\n');
const text = `<b>Корпус: ${total} документов</b>\n\n${lines}\n\nЗадайте вопрос по любой категории — отвечу по конкретным документам.`;
return [{ json: { chat_id: $node['Whitelist'].json.chat_id, text } }];

const TG_MAX = 4000;
const escapeHtml = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mdToHtml = (s) => {
  s = s.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  s = s.replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>');
  s = s.replace(/^- /gm, '• ');
  s = s.replace(/^\* /gm, '• ');
  return s;
};
const balanceTags = (s) => {
  // если split разорвал <b>...</b> или <code>...</code>, дозакрыть в конце.
  ['b', 'code'].forEach(tag => {
    const opens = (s.match(new RegExp(`<${tag}>`, 'g')) || []).length;
    const closes = (s.match(new RegExp(`</${tag}>`, 'g')) || []).length;
    if (opens > closes) s = s + `</${tag}>`.repeat(opens - closes);
    if (closes > opens) s = `<${tag}>`.repeat(closes - opens) + s;
  });
  return s;
};
const splitIntoParts = (full, max) => {
  if (full.length <= max) return [full];
  const parts = [];
  const paragraphs = full.split('\n\n');
  let current = '';
  const flush = () => { if (current) { parts.push(current); current = ''; } };
  for (const para of paragraphs) {
    const candidate = current ? current + '\n\n' + para : para;
    if (candidate.length <= max) {
      current = candidate;
      continue;
    }
    flush();
    if (para.length <= max) {
      current = para;
      continue;
    }
    // параграф сам по себе > max — split по предложениям, потом hard chunk
    const sentences = para.split(/(?<=[.!?])\s+/);
    let sCur = '';
    for (const s of sentences) {
      const sCand = sCur ? sCur + ' ' + s : s;
      if (sCand.length <= max) { sCur = sCand; continue; }
      if (sCur) { parts.push(sCur); sCur = ''; }
      if (s.length > max) {
        for (let i = 0; i < s.length; i += max) parts.push(s.slice(i, i + max));
      } else {
        sCur = s;
      }
    }
    if (sCur) parts.push(sCur);
  }
  flush();
  return parts.map(balanceTags);
};
const seenFiles = new Set();
const dedupedSources = [];
for (const s of ($json.sources || [])) {
  const file = s.file || s.chunk_id || '';
  if (file && seenFiles.has(file)) continue;
  seenFiles.add(file);
  dedupedSources.push(s);
}
const sources = dedupedSources.map((s, i) => {
  const file = escapeHtml(s.file || s.chunk_id || 'unknown');
  const section = escapeHtml(s.section || 'раздел не указан');
  return `${i + 1}. <code>${file}</code> (${section}, score ${s.score})`;
}).join('\n');
const count = dedupedSources.length;
const pluralRu = (n) => {
  const mod10 = n % 10;
  const mod100 = n % 100;
  if (mod10 === 1 && mod100 !== 11) return 'релевантный документ';
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return 'релевантных документа';
  return 'релевантных документов';
};
const summary = count > 0 ? `Найдено ${count} ${pluralRu(count)}.` : 'По базе знаний не найдено подходящих документов.';
const answer = mdToHtml(escapeHtml($json.answer));
const fullText = `${answer}\n\n${summary}${sources ? `\n\nИсточники:\n${sources}` : ''}`;
const parts = splitIntoParts(fullText, TG_MAX);
const chatId = $node['Whitelist'].json.chat_id;
const requestLogId = $json.request_log_id || '';
const totalParts = parts.length;
return parts.map((text, i) => ({
  json: {
    chat_id: chatId,
    text: totalParts > 1 ? `${text}\n\n<i>часть ${i + 1}/${totalParts}</i>` : text,
    request_log_id: requestLogId,
    is_last: i === totalParts - 1,
    part_index: i + 1,
    part_total: totalParts,
  },
}));
